mapper.select:
SELECT FROM wms_hose_fitting f
AND (f.field_name LIKE CONCAT('%', #{bo.keyword}, '%') OR f.fitting_sku LIKE CONCAT('%', #{bo.keyword}, '%') OR f.thread_spec LIKE CONCAT('%', #{bo.keyword}, '%') OR f.bore_hint LIKE CONCAT('%', #{bo.keyword}, '%'))
AND f.thread_system = #{bo.threadSystem}
AND f.seat_type = #{bo.seatType}
AND f.gender = #{bo.gender}
AND f.angle = #{bo.angle}
AND f.seen_on_sheet = 1
AND inv.quantity > 0
ORDER BY FIELD(f.thread_system, '公制', '英制', '美制'), f.thread_spec, f.seat_type, f.gender, f.angle
